    reporter = CloudWatchReporter.forRegistry(metricRegistry).namespace(NAMESPACE).prefixedWith(PREFIX).maxDatumsPerRequest(MAX_DATUMS_PER_REQUEST).withClock(Clock.defaultClock()).filter(MetricFilter.ALL).convertRatesTo(TimeUnit.SECONDS).convertDurationsTo(TimeUnit.MILLISECONDS).build(cloudWatchAsync);
