@Test
public void testGetCommitsTimelineAfter() throws IOException {
    // Should only load active timeline
    String startTs = "010";
    HoodieTableMetaClient mockMetaClient = prepareMetaClient(Arrays.asList(new HoodieInstant(COMPLETED, COMMIT_ACTION, "009", "013"), new HoodieInstant(COMPLETED, COMMIT_ACTION, "010", "010"), new HoodieInstant(COMPLETED, COMMIT_ACTION, "011", "011"), new HoodieInstant(COMPLETED, COMMIT_ACTION, "012", "012")), Arrays.asList(new HoodieInstant(COMPLETED, COMMIT_ACTION, "001", "001"), new HoodieInstant(COMPLETED, COMMIT_ACTION, "002", "002")), startTs);
    // Commit 009 will be included in result because it has greater commit completion than 010
    verifyTimeline(Arrays.asList(new HoodieInstant(COMPLETED, COMMIT_ACTION, "009"), new HoodieInstant(COMPLETED, COMMIT_ACTION, "011"), new HoodieInstant(COMPLETED, COMMIT_ACTION, "012")), TimelineUtils.getCommitsTimelineAfter(mockMetaClient, startTs, Option.of(startTs)));
    verify(mockMetaClient, never()).getArchivedTimeline(any());
    // Should load both archived and active timeline
    startTs = "001";
    mockMetaClient = prepareMetaClient(Arrays.asList(new HoodieInstant(COMPLETED, ROLLBACK_ACTION, "009", "009"), new HoodieInstant(COMPLETED, COMMIT_ACTION, "010", "010"), new HoodieInstant(COMPLETED, COMMIT_ACTION, "011", "011"), new HoodieInstant(COMPLETED, COMMIT_ACTION, "012", "012")), Arrays.asList(new HoodieInstant(COMPLETED, COMMIT_ACTION, "001", "001"), new HoodieInstant(COMPLETED, COMMIT_ACTION, "002", "002")), startTs);
